// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address nftOwner, address spender, uint256 tokenId, bytes calldata data) public {
        vm.assume(caller != address(0) && nftOwner != address(0) && spender != address(0));
        bytes4 expected = bytes4(keccak256("onERC721Received(address,address,uint256,bytes)"));
        vm.prank(caller);
        bytes4 actual = c.onERC721Received(caller, nftOwner, tokenId, data);
        assertEq(actual, expected);
    }
}
